/* mtd-pricing fallback: the mobile bleed clamp.
 *
 * The price cards are two fixed-width flex items (358px and 432px at a 390px
 * viewport, measured) inside a 358px row — 790px of card in a 358px box. The
 * export does not scroll or clip them, so the page itself scrolls sideways by
 * 22px at 390 (measured: scrollWidth 412 vs clientWidth 390) and the second
 * card is reachable only by dragging the whole document.
 *
 * A page-wide horizontal scroll is not shippable above the 360px floor, so the
 * stripe clips instead: the second card stays cut exactly where the export
 * cuts it, and the document no longer moves. `clip` rather than `hidden`
 * because a scroll container would add wheel/touch scrolling inside a section
 * that has no arrows, dots or scrollbar — the export has no such control on the
 * price row (unlike §8/§9, which do have a slider).
 *
 * Scoped to the pricing fragment's own pattern id; both the section stripe and
 * the nested card stripe carry it, and no other component does.
 */
@media (max-width: 767px) {
  [data-pattern-id='PS01'] {
    overflow-x: clip;
  }
}

/* THEME (light): the section's ground is its own glow artwork — a dark picture
 * that the export paints over a DARK ground. The bundle's light theme repaints
 * the stripe white underneath that picture, and the cards (the export's
 * translucent #1B1B1B at 70%) then composite to mid grey, which drops the card
 * ink below the contrast bar (the green promo line at 3.23:1, the micro-text at
 * 3.76:1). The section keeps the shipped dark ground in both themes: the
 * artwork is the section, not the theme.
 *
 * Value: the kit's `Theme/Primary & Background/White or Black` in its DARK mode
 * (#000) — the ground the export ships. Ledger row: docs/TOKENS.md.
 */
.theme-light [data-pattern-id='PS01'] {
  background-color: #000;
}

/* The footnote sits on that dark ground, so it keeps the shipped dark ink in
 * the light theme too: the bundle's light ink (rgba(0,0,0,0.65) on the note,
 * jade on the link) would sit on black at 1:1 and 4.23:1. Values: the kit's
 * `Theme/Text/text secondary color` and `text primary color` in their DARK
 * modes — docs/TOKENS.md.
 */
.theme-light [data-pattern-id='PS01'] .content-spot--footnotes p {
  color: rgba(255, 255, 255, 0.65);
}

.theme-light [data-pattern-id='PS01'] .content-spot--footnotes a {
  color: rgba(255, 255, 255, 0.9);
}

/* CTA row: layout for the pricing buttons. */
.mtd-pricing-cta.button--secondary {
  min-height: 48px;
  padding: 0 24px;
}

.button--secondary:hover {
  background-color: #0a5c36;
  color: #fff;
}

.button--secondary:focus-visible {
  outline: 3px solid #f00;
}

.product-card-cta-tertiary-alt:active {
  transform: scale(0.97);
}

.button-tertiary:hover {
  text-decoration: underline;
}

.button-tertiary {
  min-height: 44px;
}

'use strict';

/**
 * check-interaction-contract.js — every button of the same class must have
 * EXACTLY the same hover, focus-visible and active look.
 *
 * PART 1 (static): no button state rule (:hover/:focus/:focus-visible/:active)
 * may live anywhere except the shared vendor stylesheets (CANONICAL_CSS), and
 * no page may use an alias button class that carries its own state rule.
 *
 * PART 2 (dynamic, headless Chromium): render every PAGES entry, measure the
 * hover / focus-visible / active computed-style signature of every button in
 * GROUPS/ALIASES and fail if a group has more than one distinct look per state.
 *
 * Exit 0 only if everything passes; 1 on any violation (each printed as a
 * line starting with `FAIL:`). Final line on pass: `OK: ...`.
 *
 * Also usable as a library: module.exports = { checkInteractionContract }
 * where checkInteractionContract is async and returns { ok, failures }.
 */

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');

const GROUPS = {
  secondary: ['button--secondary'],
  primary: ['button-checkout', 'button--primary'],
  tertiary: ['button-tertiary'],
};
const ALIASES = {
  'product-card-cta-secondary-alt': 'secondary',
  'product-card-cta-primary-alt': 'primary',
  'product-card-cta-tertiary-alt': 'tertiary',
};
const PAGES = [
  'ongoing_project/MTD/variant-a/index.html',
  'ongoing_project/MTD/variant-b/index.html',
  'ongoing_project/MTD/mtd-income-tax/index.html',
  'ongoing_project/MTD/page/index.html',
  'ongoing_project/MTD/page/index-modal.html',
];
const CANONICAL_CSS = [
  'ongoing_project/MTD/mtd-income-tax/main.css',
  'ongoing_project/MTD/page/main.css',
];
const STYLE_ROOTS = ['ongoing_project/MTD', 'components'];
const SKIP_DIRS = new Set(['.work', 'Assets', 'node_modules', '.git']);

const STATE_PSEUDO = [':hover', ':focus-visible', ':focus-within', ':focus', ':active'];
const BUTTON_CLASSES = new Set([
  ...Object.values(GROUPS).flat(),
  ...Object.keys(ALIASES),
  'score-button',
]);
const PROPS = [
  'backgroundColor', 'color', 'borderTopColor', 'borderTopWidth',
  'boxShadow', 'outlineStyle', 'outlineColor', 'outlineWidth', 'textDecorationLine',
];
const PROPS_AFTER = [...PROPS, 'transform', 'opacity'];
const STATES = ['hover', 'focus', 'active'];

// ---------------------------------------------------------------- helpers

function rel(p) {
  return path.relative(ROOT, p).split(path.sep).join('/');
}

function walk(dir, out) {
  let entries;
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const e of entries) {
    if (e.isDirectory()) {
      if (SKIP_DIRS.has(e.name)) continue;
      walk(path.join(dir, e.name), out);
    } else if (e.isFile()) {
      out.push(path.join(dir, e.name));
    }
  }
  return out;
}

function stripComments(css) {
  return css.replace(/\/\*[\s\S]*?\*\//g, '');
}

/** Yield { selector, body } for every style rule, recursing into
 *  @media/@supports/@container/@layer and ignoring @keyframes/@font-face. */
function* iterRules(css) {
  let i = 0;
  const n = css.length;
  while (i < n) {
    while (i < n && /\s/.test(css[i])) i++;
    if (i >= n) break;
    if (css[i] === '}') { i++; continue; }
    if (css[i] === '@') {
      const brace = css.indexOf('{', i);
      const semi = css.indexOf(';', i);
      if (semi !== -1 && (brace === -1 || semi < brace)) { i = semi + 1; continue; }
      if (brace === -1) break;
      const name = (css.slice(i, brace).match(/^@\s*([\w-]+)/) || [, ''])[1].toLowerCase();
      let depth = 0;
      let k = brace;
      for (; k < n; k++) {
        if (css[k] === '{') depth++;
        else if (css[k] === '}' && --depth === 0) break;
      }
      if (name === 'media' || name === 'supports' || name === 'container' || name === 'layer') {
        yield* iterRules(css.slice(brace + 1, k));
      }
      i = k + 1;
      continue;
    }
    const brace = css.indexOf('{', i);
    if (brace === -1) break;
    const selector = css.slice(i, brace).trim();
    let depth = 0;
    let k = brace;
    for (; k < n; k++) {
      if (css[k] === '{') depth++;
      else if (css[k] === '}' && --depth === 0) break;
    }
    if (selector) yield { selector, body: css.slice(brace + 1, k) };
    i = k + 1;
  }
}

/** Split a selector list on top-level commas (not inside parentheses). */
function splitSelectors(sel) {
  const out = [];
  let depth = 0;
  let cur = '';
  for (const ch of sel) {
    if (ch === '(') depth++;
    else if (ch === ')') depth--;
    if (ch === ',' && depth === 0) {
      if (cur.trim()) out.push(cur.trim());
      cur = '';
    } else cur += ch;
  }
  if (cur.trim()) out.push(cur.trim());
  return out;
}

function classTokensOfSelector(sel) {
  const names = [];
  const re = /\.([A-Za-z_][\w-]*)/g;
  let m;
  while ((m = re.exec(sel))) names.push(m[1]);
  return names;
}

function hasStatePseudo(sel) {
  return STATE_PSEUDO.some((p) => sel.includes(p));
}

function isButtonStateSelector(sel) {
  if (!hasStatePseudo(sel)) return false;
  return classTokensOfSelector(sel).some((t) => BUTTON_CLASSES.has(t));
}

/** All class-attribute values of one html file. */
function classAttrsOf(html) {
  const out = [];
  const re = /class\s*=\s*("([^"]*)"|'([^']*)')/g;
  let m;
  while ((m = re.exec(html))) out.push(m[2] !== undefined ? m[2] : m[3]);
  return out;
}

function classWordIn(attrs, word) {
  return attrs.some((a) => a.split(/\s+/).includes(word));
}

function groupOfClassList(classList) {
  for (const c of classList) {
    if (ALIASES[c]) return ALIASES[c];
  }
  for (const c of classList) {
    for (const [g, names] of Object.entries(GROUPS)) {
      if (names.includes(c)) return g;
    }
  }
  return null;
}

// ---------------------------------------------------------------- PART 1

function staticChecks() {
  const failures = [];
  const fail = (msg) => { failures.push(msg); console.log('FAIL: ' + msg); };

  const files = [];
  for (const root of STYLE_ROOTS) walk(path.join(ROOT, root), files);

  const canonical = new Set(CANONICAL_CSS.map((p) => path.join(ROOT, p)));

  // alias usage in PAGES (needed for the canonical-file rule)
  const aliasUsedInPage = new Map(); // alias -> page rel
  for (const page of PAGES) {
    const abs = path.join(ROOT, page);
    let html = '';
    try { html = fs.readFileSync(abs, 'utf8'); } catch { continue; }
    const attrs = classAttrsOf(html);
    for (const alias of Object.keys(ALIASES)) {
      if (!aliasUsedInPage.has(alias) && classWordIn(attrs, alias)) {
        aliasUsedInPage.set(alias, page);
      }
    }
  }

  for (const [alias, page] of aliasUsedInPage) {
    fail(`${page}: uses alias button class ${alias}; use the shared class ${GROUPS[ALIASES[alias]][0]} instead`);
  }

  for (const file of files) {
    const ext = path.extname(file).toLowerCase();
    let sources = []; // { label, text, isCanonical }
    if (ext === '.css') {
      let text = '';
      try { text = fs.readFileSync(file, 'utf8'); } catch { continue; }
      sources.push({ label: rel(file), text, isCanonical: canonical.has(file) });
    } else if (ext === '.html') {
      let html = '';
      try { html = fs.readFileSync(file, 'utf8'); } catch { continue; }
      const re = /<style\b[^>]*>([\s\S]*?)<\/style>/gi;
      let m;
      while ((m = re.exec(html))) {
        sources.push({ label: rel(file), text: m[1], isCanonical: false });
      }
    } else continue;

    for (const src of sources) {
      const css = stripComments(src.text);
      for (const rule of iterRules(css)) {
        for (const sel of splitSelectors(rule.selector)) {
          if (!isButtonStateSelector(sel)) continue;
          if (!src.isCanonical) {
            fail(`${src.label}: button state selector outside the shared definition: ${sel}`);
            continue;
          }
          for (const token of classTokensOfSelector(sel)) {
            if (ALIASES[token] && aliasUsedInPage.has(token)) {
              fail(`${src.label}: alias button class ${token} has its own state rule (second definition of ${ALIASES[token]}): ${sel}`);
              break;
            }
          }
        }
      }
    }
  }
  return failures;
}

// ---------------------------------------------------------------- PART 2

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.map': 'application/json',
  '.txt': 'text/plain; charset=utf-8',
};

function startServer() {
  const http = require('http');
  const server = http.createServer((req, res) => {
    try {
      let urlPath = decodeURIComponent((req.url || '/').split('?')[0]);
      if (urlPath.endsWith('/')) urlPath += 'index.html';
      const abs = path.resolve(ROOT, '.' + path.posix.normalize(urlPath));
      if (abs !== ROOT && !abs.startsWith(ROOT + path.sep)) {
        res.writeHead(403);
        res.end();
        return;
      }
      const data = fs.readFileSync(abs);
      res.writeHead(200, { 'Content-Type': MIME[path.extname(abs).toLowerCase()] || 'application/octet-stream' });
      res.end(data);
    } catch {
      res.writeHead(404);
      res.end();
    }
  });
  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', () => resolve(server));
  });
}

async function dynamicChecks(failures) {
  const fail = (msg) => { failures.push(msg); console.log('FAIL: ' + msg); };

  let chromium;
  try {
    ({ chromium } = require('playwright'));
  } catch {
    fail('playwright not installed (npm i -D playwright && npx playwright install chromium)');
    return { buttons: 0, pages: PAGES.length };
  }

  const server = await startServer();
  const port = server.address().port;
  const browser = await chromium.launch({ headless: true });
  const measurements = []; // { page, group, state -> sig, classAttr, text }
  let totalButtons = 0;

  try {
    for (const pagePath of PAGES) {
      const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
      try {
        await page.route(
          (u) => /^https?:/.test(u.toString()) && u.hostname !== '127.0.0.1',
          (r) => r.abort()
        );
        await page.goto(`http://127.0.0.1:${port}/${pagePath}`, { waitUntil: 'load' }).catch(() => {});
        await page.evaluate(() => {
          document.getElementById('sage-page-gate-lock')?.remove();
          document.getElementById('sage-page-gate')?.setAttribute('hidden', '');
          document.addEventListener('click', (e) => e.preventDefault(), true);
        });
        await page.waitForTimeout(600);

        const allClasses = [...Object.values(GROUPS).flat(), ...Object.keys(ALIASES)];
        await page.evaluate((classes) => {
          window.__ic = [...document.querySelectorAll('a, button')].filter((el) =>
            classes.some((c) => el.classList.contains(c))
          );
        }, allClasses);
        const count = await page.evaluate(() => window.__ic.length);

        for (let i = 0; i < count; i++) {
          const el = (await page.evaluateHandle((i) => window.__ic[i], i)).asElement();
          if (!el) continue;
          await el.scrollIntoViewIfNeeded({ timeout: 3000 }).catch(() => {});

          const visible = await el.evaluate((e) => {
            const r = e.getBoundingClientRect();
            const cs = getComputedStyle(e);
            return r.width > 0 && r.height > 0 && cs.visibility !== 'hidden' && cs.display !== 'none';
          });
          if (!visible) { await el.dispose(); continue; }

          const hitTestable = await el.evaluate((e) => {
            const r = e.getBoundingClientRect();
            const hit = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2);
            return !!hit && (hit === e || e.contains(hit));
          });
          if (!hitTestable) { await el.dispose(); continue; }

          const meta = await el.evaluate((e) => ({
            classAttr: (e.getAttribute('class') || '').replace(/\s+/g, ' ').trim(),
            text: (e.textContent || '').trim().slice(0, 24),
            classes: [...e.classList],
          }));
          const group = groupOfClassList(meta.classes);
          if (!group) { await el.dispose(); continue; }

          const read = () => el.evaluate((e, { P, PA }) => {
            const pack = (ps, props) => {
              const c = getComputedStyle(e, ps);
              return props.map((k) => c[k]).join('|');
            };
            return pack(null, P) + ' || ' + pack('::after', PA);
          }, { P: PROPS, PA: PROPS_AFTER });

          const box = await el.boundingBox();
          if (!box) { await el.dispose(); continue; }
          const cx = box.x + box.width / 2;
          const cy = box.y + box.height / 2;

          // hover first, then active, then focus-visible
          await page.mouse.move(cx, cy);
          await page.waitForTimeout(600);
          const hover = await read();

          await page.mouse.down();
          await page.waitForTimeout(700);
          const active = await read();
          await page.mouse.up();
          await page.mouse.move(0, 0);
          await page.waitForTimeout(150);

          await el.focus();
          await page.keyboard.press('Shift');
          await page.waitForTimeout(600);
          const focus = await read();
          await el.evaluate((e) => e.blur());
          await el.dispose();

          totalButtons++;
          measurements.push({
            page: pagePath,
            group,
            classAttr: meta.classAttr,
            text: meta.text,
            hover, focus, active,
          });
        }
      } finally {
        await page.close().catch(() => {});
      }
    }
  } finally {
    await browser.close().catch(() => {});
    await new Promise((r) => server.close(r));
  }

  // group by <group>:<state>
  const byGroup = new Map(); // group -> { buttons: n, sigs: { state -> Map(sig -> [items]) } }
  for (const m of measurements) {
    if (!byGroup.has(m.group)) {
      byGroup.set(m.group, { n: 0, sigs: { hover: new Map(), focus: new Map(), active: new Map() } });
    }
    const g = byGroup.get(m.group);
    g.n++;
    for (const state of STATES) {
      const map = g.sigs[state];
      if (!map.has(m[state])) map.set(m[state], []);
      map.get(m[state]).push(m);
    }
  }

  for (const [group, g] of byGroup) {
    const counts = STATES.map((s) => g.sigs[s].size);
    console.log(`${group}: ${g.n} buttons, hover/focus/active distinct signatures = ${counts.join('/')}`);
    for (const state of STATES) {
      const map = g.sigs[state];
      if (map.size > 1) {
        fail(`${group} ${state}: ${map.size} different looks`);
        for (const [, items] of map) {
          for (const it of items.slice(0, 2)) {
            console.log(`  e.g. ${it.page} class="${it.classAttr}" text="${it.text}" sig=${it[state].slice(0, 200)}`);
          }
        }
      }
    }
  }

  return { buttons: totalButtons, pages: PAGES.length };
}

// ---------------------------------------------------------------- API

async function checkInteractionContract(argv = []) {
  const failures = staticChecks();
  let buttons = 0;
  let pages = 0;
  if (!argv.includes('--static-only')) {
    const dyn = await dynamicChecks(failures);
    buttons = dyn.buttons;
    pages = dyn.pages;
  }
  const ok = failures.length === 0;
  if (ok) {
    if (argv.includes('--static-only')) {
      console.log(`OK: static interaction contract holds across ${STYLE_ROOTS.join(', ')}; only the shared definition carries button state rules`);
    } else {
      console.log(`OK: ${buttons} buttons in ${pages} pages share one hover/focus-visible/active look per class; no overriding state rules`);
    }
  }
  return { ok, failures };
}

module.exports = { checkInteractionContract };

if (require.main === module) {
  checkInteractionContract(process.argv.slice(2))
    .then((r) => { if (!r.ok) process.exit(1); })
    .catch((e) => { console.error('FAIL: ' + (e && e.stack ? e.stack : e)); process.exit(1); });
}

